ionIssues??[])!==[]):?><div class="notice warn"><strong>Проверка действий с заявками</strong><ul><?php foreach($tripActionIssues as $issue):?><li><?=e($issue)?></li><?php endforeach;?></ul></div><?php endif;?><?php if($isFinanceRealm):?><?php if(WasteTripService::hasPreservedSettlements($trip)):?><div class="notice warn span-2"><?=e(WasteTripService::PRESERVED_SETTLEMENTS_NOTICE)?></div><?php endif;?>
